from urllib.parse import urlparse, urlunparse, parse_qs, urlencode

def apply_rewrite_rules(rules, urls):
    def host_matches_subdomain(hostname, match_value):
        """Check if hostname matches the rule (exact or wildcard subdomain)."""
        # Exact match
        if hostname == match_value:
            return True
        # Wildcard subdomain match: *.example.com -> matches sub.example.com
        if match_value.startswith('*.') and not match_value.startswith('**.'):
            base_domain = match_value[2:]  # Remove "*." prefix
            if hostname.endswith('.' + base_domain):
                remainder = hostname[:len(hostname) - len(base_domain) - 1]  # e.g. 'sub.' in 'sub.example.com'
                return remainder and '.' in remainder  # Must have at least one subdomain level
        return False

    results = []
    for url in urls:
        parsed = urlparse(url)

        matched_rule = None

        for rule in rules:
            match_type = rule['match_type']
            match_value = rule['match_value']
            action = rule['action']

            if match_type == 'path_prefix':
                if parsed.path.startswith(match_value):
                    matched_rule = rule
                    break

            elif match_type == 'host':
                if host_matches_subdomain(parsed.hostname, match_value):
                    matched_rule = rule
                    break

            elif match_type == 'query_param':
                query_params = parse_qs(parsed.query)
                if match_value in query_params:
                    matched_rule = rule
                    break

        if matched_rule is None:
            results.append(url)
        else:
            action = matched_rule['action']
            action_value = matched_rule.get('action_value', '')

            if action == 'block':
                results.append(None)
            elif action == 'strip_prefix':
                if action_value and parsed.path.startswith(action_value):
                    new_path = parsed.path[len(action_value):]
                    if not new_path or not new_path.startswith('/'):
                        new_path = '/'
                else:
                    new_path = parsed.path
                new_url = urlunparse(parsed._replace(path=new_path))
                results.append(new_url)

            elif action == 'redirect_host':
                new_netloc = action_value
