                    if new_netloc:
                        new_netloc = f"//{new_netloc}" + parsed.netloc[len(parsed.hostname) + len(':') - 2:] if parsed.port else ''
                        # Simplified: replace entire hostname only, keep port/path/query
                new_url = urlunparse(parsed._replace(netloc=new_netloc))
                results.append(new_url)
            elif action == 'add_query_param':
                query_params = parse_qs(parsed.query, keep_blank_values=True)
                key = action_value.split('=', 1)[0] if '=' in action_value else action_value
                val = action_value.split('=', 1)[1] if '=' in action_value else ''
                query_params[key] = [val]
                result_query = urlencode(query_params, doseq=True)
                new_url = urlunparse(parsed._replace(query=result_query))
                results.append(new_url)

    return results
